const requireRuntime = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = requireRuntime('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.addInitScript(() => {
    window.__touchPointerEvents = [];
    document.addEventListener('pointerdown', event => window.__touchPointerEvents.push({ type: event.type, pointerType: event.pointerType, target: event.target.id || event.target.className }));
  });
  await page.goto('http://127.0.0.1:8000', { waitUntil: 'load' });
  await page.touchscreen.tap(180, 400);
  await page.waitForTimeout(250);
  const controls = await page.locator('.mobile-controls').evaluate(element => getComputedStyle(element).display);
  const boxes = await page.evaluate(() => ['stick', 'touchUse', 'touchThrow'].map(id => {
    const r = document.getElementById(id).getBoundingClientRect();
    return { id, x: r.x + r.width / 2, y: r.y + r.height / 2 };
  }));
  for (const box of boxes) await page.touchscreen.tap(box.x, box.y);
  await page.waitForTimeout(250);
  const state = await page.evaluate(() => ({ playing, paused, stickX, stickY, lookPointer, stickPointer, pointers: window.__touchPointerEvents }));
  await page.screenshot({ path: '/tmp/opencode/mobile-after.png' });
  console.log(JSON.stringify({ controls, boxes, state, errors }, null, 2));
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
